import{a as e,_ as a,b as r,c as o,d as i}from"./chunks/automatic-three-projects-nodes.Df70EyDi.js";import{_ as d,o as s,c as n,a2 as c}from"./chunks/framework.BqDA2HS7.js";const l="/RefractRouter/screenshots/planning-history.jpg",h="/RefractRouter/screenshots/auto-fee-ledger.jpg",p="/RefractRouter/screenshots/auto-dag-nodes.jpg",g="/RefractRouter/screenshots/auto-dag-types.jpg",u="/RefractRouter/screenshots/dsh-20261014/automatic-simulated-trace.png",f="/RefractRouter/screenshots/dsh-20261014/automatic-simulated-ledger.png",P=JSON.parse('{"title":"运行记录与图形","description":"","frontmatter":{},"headers":[],"relativePath":"traces.md","filePath":"traces.md"}'),m={name:"traces.md"};function b(_,t,D,k,q,A){return s(),n("div",null,[...t[0]||(t[0]=[c('<h1 id="运行记录与图形" tabindex="-1">运行记录与图形 <a class="header-anchor" href="#运行记录与图形" aria-label="Permalink to &quot;运行记录与图形&quot;">​</a></h1><p>记录既用于排查一次任务，也用于核对模型路由是否符合策略。不同记录可以收合， 保留开始时间与执行耗时，避免多次任务混在一起难以查找。</p><p>DSH 界面把记录分成两个页签：<strong>任务 DAG</strong> 展示拆分计划与节点状态， <strong>路由轨迹</strong> 展示每次模型调用的策略原因、判别、费用与停止原因。 它们通过宿主会话引用关联核心记录；任务图还可以回放宿主保存的节点事件。 因此图形可回放不代表完整核心账本仍在原目录。</p><h2 id="两个页签" tabindex="-1">两个页签 <a class="header-anchor" href="#两个页签" aria-label="Permalink to &quot;两个页签&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页签</th><th>主要内容</th></tr></thead><tbody><tr><td>任务 DAG</td><td>自动路由计划、节点与连线、依赖、模型分配和执行状态</td></tr><tr><td>路由轨迹</td><td>模型调用流程、策略原因、Judge、接受／丢弃、费用与停止原因</td></tr></tbody></table><p>自动路由也有可审计的调用记录与轨迹。Direct 可以没有任务节点图；规划失败可能只有规划调用， 不能因为没有 DAG 就丢失费用或错误。</p><h2 id="路由轨迹页详解" tabindex="-1">路由轨迹页详解 <a class="header-anchor" href="#路由轨迹页详解" aria-label="Permalink to &quot;路由轨迹页详解&quot;">​</a></h2><p>路由轨迹页区分 <strong>Judge 原始答案</strong> 与 <strong>Router 最终动作</strong>：任务运行状态不等于质量已通过 独立验收。下面的截图来自一次真实的自动路由任务。</p><h3 id="规划路由-看每次调用-而非任务拆分" tabindex="-1">规划路由：看每次调用，而非任务拆分 <a class="header-anchor" href="#规划路由-看每次调用-而非任务拆分" aria-label="Permalink to &quot;规划路由：看每次调用，而非任务拆分&quot;">​</a></h3><figure class="doc-screenshot"><a href="/screenshots/planning-history.jpg" target="_blank" rel="noopener"><img src="'+l+'" alt="历史真实 Advisor 路由轨迹：已完成、AFP 与 CNY 分开、执行候选等待审核"></a><figcaption>2026-10-07 保存的系统截图，展示 10 月 3 日 OpenRouter Jev 的 Advisor 有限验收；属于历史真实记录。</figcaption></figure><p>这项任务要求调用一次终端工具输出 <code>OPENROUTER_ADVISOR_OK</code>，再只回复标记。 读规划记录时先看策略与状态，再逐行检查 <strong>模型／推理等级 → 用途 → 接受或丢弃 → 本次与累计金额 → 决策与证据</strong>。同一个任务可有执行、工具续接后的执行和一次审核， 费用按这些真实调用分别记账。图中的执行候选尚待审核，不表示已交付；只有 Gate 批准后 宿主才释放最终回复。金额 <code>6.49575 AFP</code> 与 <code>0.00208954 CNY</code> 使用各自单位，不能相加。 完整边界见<a href="https://github.com/AEALab/RefractRouter/blob/main/reports/jev-openrouter-20261003/README.md" target="_blank" rel="noreferrer">历史 Jev 接线报告</a>。</p><p>Stage／Composite 要看新增证据、保持计数和恢复原因；Task 要看一次初选及后续模型是否保持； Advisor 要看候选处置与复审；Escalation 要看接管是否发生及接管后未追加审核的标识。 两行相同模型不代表路由没工作，也不自动代表发生过切换。</p><h3 id="自动路由-把结构判别与最终路线分开" tabindex="-1">自动路由：把结构判别与最终路线分开 <a class="header-anchor" href="#自动路由-把结构判别与最终路线分开" aria-label="Permalink to &quot;自动路由：把结构判别与最终路线分开&quot;">​</a></h3><figure class="doc-diagram"><img src="'+e+'" alt="路由轨迹页：任务判断与最终执行路线"><figcaption>路由轨迹页的“自动路由”卡片：记录 ID、宿主轮次、端到端耗时、任务判别与最终执行路线。</figcaption></figure><p>从上到下依次核对四个区块：</p><ol><li><strong>记录头</strong>：记录 ID、宿主轮次、端到端耗时。记录 ID 是本机证据文件的名字， 可以直接用来排查。</li><li><strong>任务判断与最终执行路线</strong>：结构规则给出的结论（例如“DAG 拆分执行”）、 最终选择的执行方式、候选计划节点数与选中节点数。</li><li><strong>Judge 信息</strong>：判别后端（如 OpenRouter Jev）、原始分类、规则合并后的分类、 判别耗时与排队时间。实验性路线会明确标注。</li><li><strong>路线预测与适用范围</strong>：Direct 与 DAG 两条路线的预测成本、预测范围的边界说明。 未选择的候选路线没有被执行，预测差额不能当作实测收益。</li></ol><figure class="doc-diagram"><img src="'+a+'" alt="Jev 原始答案表格：依赖前一步输出、可独立开始、只有一项工作的概率"><figcaption>Judge 原始答案区：三个结构问题的概率，由规则合成分类，不是模型直接给出的置信度。</figcaption></figure><p>Jev 原始答案区列出每个结构问题的概率（例如“是否依赖前一步输出 0.08”）。页面同时说明： 这些分类概率由规则合成，不是模型直接给出的 Choice probability 或 confidence， 也不表示任务成功率。合同版本（如 <code>decomposition-decision-v2</code>）与规则版本 （如 <code>automatic-decomposition-hybrid-v5</code>）会一起展示。</p><h3 id="工具证据与评审" tabindex="-1">工具证据与评审 <a class="header-anchor" href="#工具证据与评审" aria-label="Permalink to &quot;工具证据与评审&quot;">​</a></h3><figure class="doc-diagram"><img src="'+r+'" alt="工具证据、评审与停止原因：宿主工具回执列表"><figcaption>工具回执区：每条回执显示节点名、工具、completed 状态与调用 ID。completed 表示回执已返回，不自动证明命令成功。</figcaption></figure><p>工具证据区列出宿主返回的结构化回执：节点（如 answer）、工具名（如 bash）、 状态（completed）和调用 ID。<strong>completed 表示回执已返回，不自动证明测试成功或命令退出为零。</strong> 评审行显示是否完成、分数、原始结论与门槛验收结果——最终运行状态与质量验收是两个概念。</p><h3 id="费用与预算" tabindex="-1">费用与预算 <a class="header-anchor" href="#费用与预算" aria-label="Permalink to &quot;费用与预算&quot;">​</a></h3><figure class="doc-diagram"><img src="'+h+'" alt="费用与预算表格：参考成本占用、现金结算、待核对预留"><figcaption>费用与预算区：按用途区分参考成本占用与现金用量；参考估值不与现金占用相加。</figcaption></figure><p>费用账本按用途（生产、规划、评审等）分列：参考成本占用、现金用量结算／待核对、 当时现金预算与剩余。逐模型的准入记录显示实际分配状态；旧记录未保存的检查项会提示 “通过准入不等于预算可执行”。</p><h2 id="任务-dag-页详解" tabindex="-1">任务 DAG 页详解 <a class="header-anchor" href="#任务-dag-页详解" aria-label="Permalink to &quot;任务 DAG 页详解&quot;">​</a></h2><figure class="doc-diagram"><img src="'+p+'" alt="任务 DAG 页：执行节点卡片与角色节点说明"><figcaption>DAG 视图：每个节点卡片显示节点 ID、正式类型、难度风险、职责说明、分配模型与状态。</figcaption></figure><p>DAG 视图里每个节点卡片包含五类信息：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>节点 ID</td><td>规划器命名的标识，没有固定清单</td><td>answer、forecast、risk</td></tr><tr><td>正式类型</td><td>planning／extraction／synthesis／generation／verification</td><td>生成 · generation</td></tr><tr><td>难度与风险</td><td>规划器估计的 low／medium／high</td><td>难度 medium · 风险 high</td></tr><tr><td>职责说明</td><td>这个节点要产出什么</td><td>完整回答当前用户任务</td></tr><tr><td>模型与状态</td><td>分配的 provider／模型（推理等级）与运行状态</td><td>ark/deepseek-v4-flash (low) · 已完成</td></tr></tbody></table><p>上图是单交付节点 Direct 的展示：即使有准入角色和 <code>answer</code> 连线，也不应称为多分支 DAG。 箭头表示下游需要上游结果；同层无依赖的节点在合法调度下可以并行调用模型。</p><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/automatic-three-projects-dag.png" target="_blank" rel="noopener"><img src="'+o+'" alt="2026 年 10 月 14 日实际回放的三项目多节点 DAG"></a><figcaption>三项目真实历史 DAG：proj_a、proj_b、proj_c 相互独立，answer 等待三者；虚线角色不计作交付节点。</figcaption></figure><p>完整输入、每个分支的输出合同、依赖、实际模型与历史账单见 <a href="./automatic.html#真实案例二-三项目独立分析-执行多节点-dag">三项目案例</a>。 图中三个分支都使用 GLM 5.3，难度／风险为 low；汇总节点为 medium。 难度是规划器估计，不能由节点名或框的颜色推断任务质量。</p><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/automatic-three-projects-nodes.png" target="_blank" rel="noopener"><img src="'+i+'" alt="实际节点完整说明与依赖：三个 synthesis 节点与一个 generation 汇总节点"></a><figcaption>展开详情核对“只使用本项目数据”的约束与 answer 的三个上游；长职责以详情为准。</figcaption></figure><h3 id="流程角色节点" tabindex="-1">流程角色节点 <a class="header-anchor" href="#流程角色节点" aria-label="Permalink to &quot;流程角色节点&quot;">​</a></h3><p>DAG 页还有一类<strong>虚线边框的角色节点</strong>：它们表示控制与质量环节，不是普通交付节点。</p><table tabindex="0"><thead><tr><th>角色</th><th>作用与出现条件</th></tr></thead><tbody><tr><td>规划前输入分级 · role-classifier</td><td>规划模型调用前检查任务输入的敏感级别与部署许可</td></tr><tr><td>节点放置准入 · role-placement</td><td>规划完成后检查敏感级别与可用部署路线</td></tr><tr><td>最终评审 · final-judge</td><td>按自适应审核规则决定是否需要独立评审</td></tr></tbody></table><p>角色节点按核心进度显示运行、完成、阻断或跳过状态，帮助区分“流程没走到”和“执行失败”。</p><figure class="doc-diagram"><img src="'+g+'" alt="任务节点正式类型表格：规划、提取、综合、生成、验证"><figcaption>节点正式类型表：类型由实际执行节点的职责决定，不由节点名称决定。</figcaption></figure><p>节点 ID（forecast、drivers、trend、answer）是规划器起的名字，没有固定清单； 正式类型（规划、提取、综合、生成、验证）描述职责。难度与风险由规划器估计， 模型分配还考虑预算、上下文与输出需求及核心配置，不由节点名称直接决定。</p><h2 id="每次记录应该看什么" tabindex="-1">每次记录应该看什么 <a class="header-anchor" href="#每次记录应该看什么" aria-label="Permalink to &quot;每次记录应该看什么&quot;">​</a></h2><ol><li>展开本次记录，核对开始时间、总耗时与当前／最终状态。</li><li>图形中选择节点或调用，查看真实 provider、模型、推理等级及用途。</li><li>核对模型选择、保持、恢复、返工或接管的原因。</li><li>查看实际工具证据、原始 Judge 结论、规则版本与实验标识。</li><li>查看本次与累计参考／现金费用、未派发保护及待核对预留。</li></ol><p>模型首字时间、审核等待与用户首次实际看到文字的时间不同：待审核候选已经有 token， 不表示用户已经获得可交付答案。图形与记录随运行事件更新，旧记录缺字段不使用今天的设置补写。</p><h2 id="状态的含义" tabindex="-1">状态的含义 <a class="header-anchor" href="#状态的含义" aria-label="Permalink to &quot;状态的含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>解释</th></tr></thead><tbody><tr><td>运行中／等待审核</td><td>路由尚未形成可交付终态</td></tr><tr><td>已完成</td><td>冻结执行流程完成；独立质量结果另看</td></tr><tr><td>跳过审核</td><td>命中策略跳过条件，不等于独立质量通过</td></tr><tr><td>已接受／已丢弃</td><td>候选是否交给宿主；丢弃调用仍记账</td></tr><tr><td>未审定停止</td><td>证据或审核不足，候选没有正常交付</td></tr><tr><td>待核对</td><td>已派发但结果／用量不明，保留预留</td></tr></tbody></table><h3 id="如何识别模拟与历史证据缺失" tabindex="-1">如何识别模拟与历史证据缺失 <a class="header-anchor" href="#如何识别模拟与历史证据缺失" aria-label="Permalink to &quot;如何识别模拟与历史证据缺失&quot;">​</a></h3><p>2026-10-14 我们实际在 DSH 选择 <strong>自动路由（模拟）</strong> 并提交一项文档演示，得到记录 <code>20261014T032055Z-1f592764c5ae</code>。这是系统真实运行的模拟路径，外部付费模型调用为零。</p><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/automatic-simulated-trace.png" target="_blank" rel="noopener"><img src="'+u+'" alt="本轮 DSH 模拟记录：状态 simulated、模板预览与一条交付节点"></a><figcaption>本轮实际提交的模拟任务。simulated 与 template-preview 明确区分演示和真实模型执行。</figcaption></figure><p>该记录使用安装验证模板，只产生一个交付节点。即使处理方式栏出现 DAG 字样，也不能把它 当成真实多分支计划。读取时应结合 <code>simulated</code>、规划原因与节点列表，真实拆分看上面的历史案例。</p><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/automatic-simulated-ledger.png" target="_blank" rel="noopener"><img src="'+f+'" alt="本轮模拟费用账本：参考用量与模拟模型分配"></a><figcaption>模拟账本演示费用字段；显示的 0.00028 CNY 是模拟计算值，不是实际支付。</figcaption></figure><p>若历史页提示“运行证据不存在”，先核对 <code>runsDir</code> 与记录 ID。宿主可能仍保留节点图， 但账本与 Judge 原始答案已经无法在当前目录读取。应引用原公开报告或恢复原证据位置， 不要用今天的设置填充缺失的模型、预算、结果或价格。</p><h2 id="费用看起来不对时" tabindex="-1">费用看起来不对时 <a class="header-anchor" href="#费用看起来不对时" aria-label="Permalink to &quot;费用看起来不对时&quot;">​</a></h2><p>先区分参考估值与现金，再核对 token 计价单位、缓存互斥、推理 token 是否重复相加、 真实提供方、价目表版本和失败尝试。订阅参考值不能直接当作实际账单。 不要删除错误记录、清零待核对预留或只统计最终成功那次调用。</p><h2 id="本地记录" tabindex="-1">本地记录 <a class="header-anchor" href="#本地记录" aria-label="Permalink to &quot;本地记录&quot;">​</a></h2><p>DSH 插件保存到配置的 <code>runsDir</code>；默认工作目录中的 <code>.refractagent/runs</code>。 独立网关使用启动时指定的 <code>--runs-dir</code>。审计材料可能包含任务上下文，应保存在合适的本地权限下。 导出公开报告时不包含凭证或原始私有会话。</p>',53)])])}const v=d(m,[["render",b]]);export{P as __pageData,v as default};
